import base64, re
raw = open('/tmp/png_text.txt','rb').read()
b = base64.b64decode(raw)
def rot13_bytes(x):
    out=bytearray()
    for c in x:
        if 65<=c<=90: out.append(65+((c-65+13)%26))
        elif 97<=c<=122: out.append(97+((c-97+13)%26))
        else: out.append(c)
    return bytes(out)
best=[]
for k in range(256):
    x = bytes(c^k for c in b)
    r = rot13_bytes(x)
    if not all(32<=c<127 for c in r): continue
    if re.fullmatch(r'[A-Za-z0-9+/=]+', r):
        best.append((k, r))
for k, r in best:
    print(k, r)
    print("   b64decode:", base64.b64decode(r)[:120])
EOF"}

